import{_ as l,C as a,o as u,c as d,j as t,a as n,E as s,a2 as i}from"./chunks/framework.TaNiW7i8.js";const y=JSON.parse('{"title":"Synchroniser la mémoire","description":"","frontmatter":{"title":"Synchroniser la mémoire"},"headers":[],"relativePath":"agent/synchroniser.md","filePath":"agent/synchroniser.md"}'),m={name:"agent/synchroniser.md"};function p(g,e,h,f,v,q){const o=a("AskExample"),r=a("Ask"),c=a("Capture");return u(),d("div",null,[e[0]||(e[0]=t("h1",{id:"synchroniser-la-memoire",tabindex:"-1"},[n("Synchroniser la mémoire "),t("a",{class:"header-anchor",href:"#synchroniser-la-memoire","aria-label":'Permalink to "Synchroniser la mémoire"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Ce parcours sert à garder la mémoire à jour entre vos postes, avec git : voir où en est le dépôt, synchroniser, commiter vos changements, résoudre un conflit. L'application le fait en un clic ; l'agent le fait par quatre outils, avec des garde-fous.",-1)),e[2]||(e[2]=t("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[n("Ce que vous demandez à l'agent "),t("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),s(o,{tool:"mem_git_status"}),s(o,{tool:"mem_git_sync"}),s(o,{tool:"mem_git_commit"}),s(r,{say:"Il y a un conflit avec le distant : montre-moi les trois versions de chaque fichier.",verb:"mem_git_resolve",family:"git"}),e[3]||(e[3]=i('<p>La synchronisation n&#39;est pas automatique : c&#39;est l&#39;agent qui appelle <code>mem_git_sync</code>, quand vous le lui demandez (« synchronise la mémoire », « où en est git ? ») ou quand il le juge utile. Les procédures livrées (voir <a href="/Kessho/agent/connecter.html">Connecter l&#39;agent</a>) l&#39;invitent à le faire au début d&#39;une session, avec la reprise, et en fin de session, avec l&#39;archive ; un agent qui ne les suit pas ne le fera pas de lui-même.</p><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><ol><li><p><a href="/Kessho/reference/mcp/git.html#mem-git-status"><code>mem_git_status</code></a> rend l&#39;état du dépôt : branche, distant (sans identifiants), avance et retard, changements non commités, opération en cours, fichiers portant des marqueurs de conflit, état du greffon Obsidian Git. Il n&#39;écrit rien et n&#39;utilise <strong>pas le réseau</strong> par défaut ; <code>fetch: true</code> interroge d&#39;abord le distant. Si git est introuvable, l&#39;état le dit avec la commande d&#39;installation, et l&#39;agent vous la relaie sans la lancer.</p></li><li><p><a href="/Kessho/reference/mcp/git.html#mem-git-sync"><code>mem_git_sync</code></a> (aucun paramètre) récupère, rebase vos commits locaux si le distant a avancé, puis pousse. <strong>Jamais forcé, jamais de mise de côté automatique.</strong> Un vrai conflit <strong>annule</strong> le rebase : le dépôt revient à l&#39;état d&#39;avant, aucun marqueur n&#39;est laissé, et les fichiers en cause sont rendus. Il est refusé si des changements non commités empêchent le rebase.</p></li><li><p><a href="/Kessho/reference/mcp/git.html#mem-git-commit"><code>mem_git_commit</code></a> commite les changements non commités (<code>paths</code> pour une partie seulement, sinon tous) avec <code>message</code> (non vide, 1 000 caractères au plus), puis pousse (<code>push: false</code> pour ne pas pousser). <strong>Il n&#39;est à appeler qu&#39;avec l&#39;accord explicite de l&#39;utilisateur</strong> : ces changements sont les vôtres. Il refuse un fichier qui porte des marqueurs de conflit, sauf <code>allow_markers: true</code> pour un fichier qui ne fait que les citer.</p></li><li><p><a href="/Kessho/reference/mcp/git.html#mem-git-resolve"><code>mem_git_resolve</code></a> résout un conflit <strong>réel</strong>, en deux temps :</p><ul><li><strong>sans <code>resolutions</code></strong>, il inspecte : il rend, pour chaque fichier en conflit, ses trois versions (<code>base</code>, <code>local</code>, <code>distant</code>) et une <code>empreinte</code>, puis annule : le dépôt ne change pas ;</li><li><strong>avec <code>resolutions</code></strong> (le texte résolu de chaque fichier, ou <code>keep: &quot;local&quot;</code> ou <code>&quot;distant&quot;</code>) et l&#39;<code>empreinte</code> rendue (à redonner dans <code>fingerprint</code>), il refait la fusion, écrit les textes, commite et pousse. Si le dépôt ou le distant a bougé entre-temps, rien n&#39;est fait ; aucun marqueur n&#39;est jamais accepté ni laissé.</li></ul><p>Le catalogue demande de ne l&#39;employer <strong>qu&#39;avec l&#39;accord de l&#39;utilisateur sur le texte fusionné</strong>.</p></li></ol><h3 id="ce-que-l-agent-ne-fait-pas" tabindex="-1">Ce que l&#39;agent ne fait pas <a class="header-anchor" href="#ce-que-l-agent-ne-fait-pas" aria-label="Permalink to &quot;Ce que l&#39;agent ne fait pas&quot;">​</a></h3><ul><li>Initialiser le dépôt et connecter un distant sont des gestes <strong>de l&#39;application</strong> (<strong>Réglages › Synchronisation</strong>) : aucun outil ne les fait.</li><li>Il ne force jamais une poussée et ne commite pas vos changements de sa propre initiative.</li></ul><h3 id="l-automatisme-sur-chaque-ecriture" tabindex="-1">L&#39;automatisme sur chaque écriture <a class="header-anchor" href="#l-automatisme-sur-chaque-ecriture" aria-label="Permalink to &quot;L&#39;automatisme sur chaque écriture&quot;">​</a></h3><p>Quand la mémoire est un dépôt git et que la case <strong>Automatisme</strong> (« Les agents commitent et synchronisent automatiquement ») est cochée, chaque outil d&#39;agent qui <strong>écrit</strong> est encadré : avant d&#39;écrire il vérifie le distant, après il commite ce qu&#39;il a touché, et lui seul, puis pousse. Vos changements non commités ne partent pas avec lui, sauf un fichier que vous aviez déjà modifié et que l&#39;outil réécrit : celui-là part avec le commit, qui le nomme (ligne <code>Kessho-Embarque</code>), et l&#39;agent doit vous le dire. Les outils de lecture ne lancent pas git ; <code>mem_git_sync</code>, <code>mem_git_commit</code> et <code>mem_git_resolve</code> sont hors de cet encadrement parce qu&#39;ils sont eux-mêmes le geste.</p><p>Le résultat d&#39;un outil d&#39;écriture porte alors un compte rendu de synchronisation, que l&#39;agent lit à chaque fois :</p><table tabindex="0"><thead><tr><th><code>statut</code></th><th>Ce que cela veut dire</th><th>Ce que fait l&#39;agent</th></tr></thead><tbody><tr><td><code>synchronise</code></td><td>Commité et poussé.</td><td>Rien.</td></tr><tr><td><code>commite_local</code></td><td>Commité ici, pas poussé (hors ligne, pas de distant, authentification refusée…).</td><td>Vous le dit en une ligne, avec le motif.</td></tr><tr><td><code>en_attente</code></td><td>Commité, mais vos changements non commités empêchent la mise à jour depuis le distant.</td><td>Vous le dit et <strong>propose</strong> <code>mem_git_commit</code> après que vous les avez relus.</td></tr><tr><td><code>ignore</code></td><td>Git n&#39;a rien fait (automatisme désactivé, pas de dépôt, git introuvable…).</td><td>Rien, sauf pour relayer la commande d&#39;installation de git.</td></tr><tr><td><code>conflit</code></td><td>Un conflit réel : le rebase est annulé et <strong>l&#39;outil n&#39;a rien écrit</strong>.</td><td>S&#39;arrête et passe par <code>mem_git_resolve</code>, avec votre accord.</td></tr><tr><td><code>erreur</code></td><td>Dépôt occupé, opération déjà en cours, ou reprise impossible.</td><td>Vous le dit et réessaie un peu plus tard ; il ne supprime jamais <code>index.lock</code>.</td></tr></tbody></table><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2>',10)),s(c,{name:"synchro",alt:"La synchronisation de la mémoire dans les réglages : fichiers modifiés depuis le dernier commit et message de commit en cours de saisie."}),e[4]||(e[4]=i('<p>L&#39;application montre le même dépôt, et c&#39;est elle qui fait en un clic ce que <code>mem_git_sync</code> fait par l&#39;agent : le bouton <strong>Synchroniser la mémoire</strong> de la barre d&#39;état commite, récupère, puis pousse. Le champ <strong>GIT</strong> dit où en est le dépôt (à jour, N à pousser, N à récupérer, conflit…), et <strong>Réglages › Synchronisation</strong> porte les gestes <strong>Synchroniser</strong>, <strong>Récupérer</strong>, <strong>Pousser</strong>, le <strong>Message de commit</strong>, le distant et la case <strong>Automatisme</strong>. Tout est décrit dans <a href="/Kessho/guide/sync.html">Synchronisation</a>.</p><p>Une différence à connaître : le bouton commite <strong>tout</strong> ce qui a changé sous un message automatique (« vault backup: … »), alors que l&#39;agent ne commite vos changements qu&#39;avec votre accord.</p>',2))])}const b=l(m,[["render",p]]);export{y as __pageData,b as default};
